import{_ as r,o as a,a as t,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"SuperKernel","link":"/guide/programming_guide/advanced_programming/super_kernel/principles"},{"text":"原理介绍","link":"/guide/programming_guide/advanced_programming/super_kernel/principles"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/super_kernel/principles.md","filePath":"guide/programming_guide/advanced_programming/super_kernel/principles.md","outlineHeaders":[{"level":2,"title":"概述","slug":"概述","link":"#概述"},{"level":2,"title":"性能收益来源","slug":"性能收益来源","link":"#性能收益来源"},{"level":2,"title":"支持的开启方式","slug":"支持的开启方式","link":"#支持的开启方式"},{"level":2,"title":"算子适配说明","slug":"算子适配说明","link":"#算子适配说明"}],"lastUpdated":1787050286000}'),i={name:"guide/programming_guide/advanced_programming/super_kernel/principles.md"};function n(d,e,p,s,o,c){return a(),t("div",null,[...e[0]||(e[0]=[l('<div><article class="markdown-body"><h1>原理介绍</h1><h2 id="概述">概述<a class="header-anchor" href="#概述">​</a></h2><p>SuperKernel是一种算子的二进制融合技术。与源码融合不同，它聚焦于核函数（Kernel）的二进制调度方案优化，在已编译的二进制代码基础上，将多个子核函数（Kernel）融合创建出一个超级核函数（Kernel）（简称SuperKernel），由该SuperKernel以子函数调用的方式整合多个核函数（Kernel），从而优化计算任务、提升性能和资源利用率。</p><p>与单算子下发相比，SuperKernel技术能够减少Task调度的等待时间和调度开销，同时利用Task间隙资源进一步优化算子头开销，提升推理性能。</p><p>开启SuperKernel融合优化后，系统会自动识别图内可被融合的算子，并生成SuperKernel进行计算。同时框架提供标定SuperKernel范围的能力，支持用户根据实际业务需求对融合范围内的算子进行标记和优化配置。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明 SuperKernel适用于如下型号：</p><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT，该型号下SuperKernel特性是试验特性，在后续版本中会调整或改进，不保证后续兼容性，请开发者在使用过程中关注后续版本更新。</li></ul></div></div><h2 id="性能收益来源">性能收益来源<a class="header-anchor" href="#性能收益来源">​</a></h2><p>相对于单算子下发，SuperKernel主要通过以下方式带来性能收益：</p><ul><li><strong>减少核函数（Kernel）启动开销</strong>：原本需要多次启动的子核函数（Kernel），被统一通过一次SuperKernel启动完成，减少了任务调度开销。</li><li><strong>减少Task调度等待时间</strong>：避免了多个独立Task之间的调度间隙。</li><li><strong>算子间流水并行</strong>：通过SuperKernel内提供的任务间同步接口（<a href="../../../../api/SIMD-API/basic_api/sync_control/inter_task_sync/SetNextTaskStart.html">SetNextTaskStart</a>、<a href="../../../../api/SIMD-API/basic_api/sync_control/inter_task_sync/WaitPreTaskEnd.html">WaitPreTaskEnd</a>），可以让子核函数（Kernel）之间的部分指令实现并行执行，进一步压缩端到端耗时。</li></ul><h2 id="支持的开启方式">支持的开启方式<a class="header-anchor" href="#支持的开启方式">​</a></h2><p>当前SuperKernel特性通过PyTorch图模式开启，主要有如下两种方式：</p><table><thead><tr><th>开启方式</th><th>说明</th></tr></thead><tbody><tr><td>npugraph_ex后端</td><td>在<code>torch.compile</code>的<code>options</code>中传入<code>super_kernel_optimize=True</code>开启SuperKernel融合；如需控制融合范围，可通过<code>torch.npu.super_kernel_scope_begin/end</code>进行标定。具体请参考<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/npugraph_ex/advanced/superkernel.md">SuperKernel功能</a>。</td></tr><tr><td>GE图模式</td><td>通过<code>torchair.scope.super_kernel</code>作用域标定融合范围，配合TorchAir的CompilerConfig开启。具体请参考<a href="https://www.hiascend.com/document/detail/zh/Pytorch/latest/devguide/TorchAir/docs/zh/ascend_ir/features/advanced/super_kernel_scope.md">图内标定SuperKernel范围</a>。</td></tr></tbody></table><h2 id="算子适配说明">算子适配说明<a class="header-anchor" href="#算子适配说明">​</a></h2><p>CANN包发布的主流模型常用算子已支持SuperKernel融合。用户自定义的Ascend C算子如需支持SuperKernel，需要满足一定适配条件，参考如下算子适配和自验证说明：</p><ul><li><a href="operator_adaptation.html">算子适配说明</a>：算子要融合进SuperKernel需要满足的通用约束（与具体的开启方式无关）。</li><li><a href="operator_self_verification.html">算子自验证说明</a>：在两种PyTorch图模式下分别对单个算子进行SuperKernel融合验证的样例。</li><li><a href="kernel_direct_call_adaptation.html">核函数（Kernel）直调算子额外适配说明</a>：对于使用<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>方式开发的Ascend C算子，进入SuperKernel前需要进行的额外适配工作。</li></ul></article></div>',1)])])}const _=r(i,[["render",n]]);export{h as __pageData,_ as default};
